#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ACCEPTANCE_DIR="$ROOT/acceptance/S6_public_launch/latest"
SUMMARY_FILE="$ACCEPTANCE_DIR/release-review-packet-integrity.json"
if [[ -v TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_INTEGRITY_SUMMARY && -n "$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_INTEGRITY_SUMMARY" ]]; then
  SUMMARY_FILE="$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_INTEGRITY_SUMMARY"
fi

PACKET_JSON="$ACCEPTANCE_DIR/release-review-packet.json"
PACKET_MD="$ACCEPTANCE_DIR/release-review-packet.md"
PACKET_LOG="$ACCEPTANCE_DIR/release-review-packet-integrity-packet.log"
if [[ -v TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_JSON && -n "$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_JSON" ]]; then
  PACKET_JSON="$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_JSON"
fi
if [[ -v TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_MD && -n "$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_MD" ]]; then
  PACKET_MD="$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_MD"
fi
if [[ -v TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_LOG && -n "$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_LOG" ]]; then
  PACKET_LOG="$TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_LOG"
fi
CHECK_RESULTS="$(mktemp)"
FAILURE_RESULTS="$(mktemp)"
PACKET_ARTIFACTS_TSV="$(mktemp)"
REFRESH_PACKET=1
declare -A PACKET_ARTIFACT_PATH_BY_ID=()
PACKET_ARTIFACT_COUNT=0
trap 'rm -f "$CHECK_RESULTS" "$FAILURE_RESULTS" "$PACKET_ARTIFACTS_TSV"' EXIT

for arg in "$@"; do
  case "$arg" in
    --no-refresh)
      REFRESH_PACKET=0
      ;;
    *)
      printf 'unknown option: %s\n' "$arg" >&2
      exit 2
      ;;
  esac
done

# shellcheck source=scripts/release_review_acceptance_lock.sh
source "$ROOT/scripts/release_review_acceptance_lock.sh"
trnm_acquire_release_review_acceptance_lock "$ACCEPTANCE_DIR"

add_check() {
  local name="$1"
  local status="$2"
  local path="$3"
  local detail="$4"
  local expected="${5:-}"
  local actual="${6:-}"
  jq -nc \
    --arg name "$name" \
    --arg status "$status" \
    --arg path "$path" \
    --arg detail "$detail" \
    --arg expected "$expected" \
    --arg actual "$actual" \
    '{name: $name, status: $status, path: $path, detail: $detail, expected: (if $expected == "" then null else $expected end), actual: (if $actual == "" then null else $actual end)}' >>"$CHECK_RESULTS"
}

require_json_expr() {
  local name="$1"
  local path="$2"
  local expr="$3"
  local detail="$4"
  if [[ ! -f "$path" ]]; then
    add_check "$name" fail "$path" missing
  elif jq -e "$expr" "$path" >/dev/null; then
    add_check "$name" ok "$path" "$detail"
  else
    add_check "$name" fail "$path" "$detail"
  fi
}

packet_artifact_path() {
  local artifact_id="$1"
  printf '%s\n' "${PACKET_ARTIFACT_PATH_BY_ID[$artifact_id]:-}"
}

load_packet_artifacts() {
  PACKET_ARTIFACT_PATH_BY_ID=()
  PACKET_ARTIFACT_COUNT=0
  : >"$PACKET_ARTIFACTS_TSV"
  if [[ ! -f "$PACKET_JSON" ]]; then
    return
  fi
  jq -r '(.artifacts // [])[] | [.id, .path, (.sha256 // ""), ((.bytes // "") | tostring), (.contract_version // ""), (.status // "")] | @tsv' "$PACKET_JSON" >"$PACKET_ARTIFACTS_TSV"
  local id
  local path
  local expected_sha
  local expected_bytes
  local expected_contract
  local expected_status
  while IFS=$'\t' read -r id path expected_sha expected_bytes expected_contract expected_status; do
    [[ -z "$id" ]] && continue
    PACKET_ARTIFACT_PATH_BY_ID["$id"]="$path"
    PACKET_ARTIFACT_COUNT=$((PACKET_ARTIFACT_COUNT + 1))
  done <"$PACKET_ARTIFACTS_TSV"
}

require_artifact_json_expr() {
  local name="$1"
  local artifact_id="$2"
  local expr="$3"
  local detail="$4"
  local path
  path="$(packet_artifact_path "$artifact_id")"
  if [[ -z "$path" ]]; then
    add_check "$name" fail "$artifact_id" missing_packet_artifact
  else
    require_json_expr "$name" "$path" "$expr" "$detail"
  fi
}

require_artifact_text_contains() {
  local name="$1"
  local artifact_id="$2"
  local detail="$3"
  shift 3
  local path
  path="$(packet_artifact_path "$artifact_id")"
  if [[ -z "$path" ]]; then
    add_check "$name" fail "$artifact_id" missing_packet_artifact
    return
  fi
  if [[ ! -f "$path" ]]; then
    add_check "$name" fail "$path" missing
    return
  fi

  local pattern
  for pattern in "$@"; do
    if ! grep -Fq -- "$pattern" "$path"; then
      add_check "$name" fail "$path" "$detail" "$pattern" missing
      return
    fi
  done
  add_check "$name" ok "$path" "$detail"
}

require_artifact_ppm_header() {
  local name="$1"
  local artifact_id="$2"
  local min_bytes="$3"
  local expected_width="${4:-1280}"
  local expected_height="${5:-720}"
  local path
  path="$(packet_artifact_path "$artifact_id")"
  if [[ -z "$path" ]]; then
    add_check "$name" fail "$artifact_id" missing_packet_artifact
    return
  fi
  if [[ ! -f "$path" ]]; then
    add_check "$name" fail "$path" missing
    return
  fi

  local header
  local bytes
  local expected_header
  header="$(head -n 3 "$path" || true)"
  bytes="$(wc -c <"$path" | tr -d ' ')"
  expected_header="$(printf 'P3\n%s %s\n255' "$expected_width" "$expected_height")"
  if [[ "$header" == "$expected_header" && "$bytes" -gt "$min_bytes" ]]; then
    add_check "$name" ok "$path" ppm_header_and_size_match "P3 ${expected_width}x${expected_height} > ${min_bytes} bytes" "$bytes"
  else
    add_check "$name" fail "$path" ppm_header_or_size_mismatch "P3 ${expected_width}x${expected_height} > ${min_bytes} bytes" "bytes=${bytes}"
  fi
}

require_artifact_json_expr_when_packet_count_at_least() {
  local name="$1"
  local artifact_id="$2"
  local min_artifact_count="$3"
  local expr="$4"
  local detail="$5"
  local artifact_count="$PACKET_ARTIFACT_COUNT"
  if [[ "$artifact_count" -lt "$min_artifact_count" ]]; then
    add_check "$name" skipped "$artifact_id" legacy_packet_artifact_count "$min_artifact_count" "$artifact_count"
    return
  fi
  require_artifact_json_expr "$name" "$artifact_id" "$expr" "$detail"
}

require_artifact_ppm_header_when_packet_count_at_least() {
  local name="$1"
  local artifact_id="$2"
  local min_artifact_count="$3"
  local min_bytes="$4"
  local expected_width="${5:-1280}"
  local expected_height="${6:-720}"
  local artifact_count="$PACKET_ARTIFACT_COUNT"
  if [[ "$artifact_count" -lt "$min_artifact_count" ]]; then
    add_check "$name" skipped "$artifact_id" legacy_packet_artifact_count "$min_artifact_count" "$artifact_count"
    return
  fi
  require_artifact_ppm_header "$name" "$artifact_id" "$min_bytes" "$expected_width" "$expected_height"
}

if [[ "$REFRESH_PACKET" -eq 1 ]]; then
  if TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_JSON="$PACKET_JSON" \
    TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_MD="$PACKET_MD" \
    "$ROOT/scripts/check_trillionnium_world_release_review_packet.sh" >"$PACKET_LOG" 2>&1; then
    add_check packet_refresh ok "$PACKET_LOG" refreshed
  else
    add_check packet_refresh fail "$PACKET_LOG" failed
  fi
else
  add_check packet_refresh skipped "$PACKET_LOG" no_refresh_requested
fi

load_packet_artifacts

require_json_expr packet_contract "$PACKET_JSON" '.contract_version == "trillionnium_world_release_review_packet_v1"' "packet contract matches"
require_json_expr packet_boundary "$PACKET_JSON" '.android_s5_real_device_claimed == false and .proof_scope == "host_side_bevy_runtime_replay_not_android_real_device"' "packet keeps Android S5 no-claim boundary"
require_json_expr packet_review_status "$PACKET_JSON" '.ready_for_release_review == true and (.status == "release_review_packet_ready_with_public_launch_blockers" or .status == "release_review_packet_green")' "packet is ready for review or public launch review"
require_json_expr packet_missing_artifacts "$PACKET_JSON" '(.missing_artifacts // []) | length == 0' "packet reports no missing artifacts"
require_json_expr packet_artifact_count "$PACKET_JSON" '((.artifacts // []) | length) as $count | ([120, 121, 124, 126, 127, 128] | index($count)) != null' "packet has expected one hundred twenty, one hundred twenty-one, one hundred twenty-four, one hundred twenty-six, one hundred twenty-seven, or one hundred twenty-eight artifacts including visible button hit-test map, live-window mouse hit-test sequence, classic playtest launcher, playtest handoff readiness/packet/Markdown, First Contact Basin source-manifest spec, full screen/UI replication, shell/meta UI replication, match setup UI replication, campaign outcome UI readiness, campaign UI continuity JSON/PPM, in-match HUD/state replication, session state continuity, combat readability/pressure readiness, camera/minimap sync JSON/PPM, full-game visual/UI replication JSON/PPM, OpenRA screen-for-screen UI replication JSON/PPM, OpenRA engine port asset parity JSON/PPM, production desktop review packet, evidence intake JSON/Markdown, evidence kit JSON/Markdown, evidence bundle JSON/Markdown, operator handoff JSON/Markdown, checkpoint manifest, packet semantic negative fixtures, CEX adapter readiness, Bevy desktop/runtime evidence, classic RTS semantic evidence, bot executor evidence, public-launch blocker/evidence-kit artifacts, and external-evidence validators"
require_json_expr packet_assembly_review "$PACKET_JSON" '
