    and ($review.reviewed_runtime_artifact_ids | index("native_bevy_classic_rts_first_contact_basin_spec") != null)
    and ($review.reviewed_runtime_artifact_ids | index("native_bevy_classic_rts_full_game_visual_ui_replication") != null)
    and ($review.reviewed_packet_fixture_ids | index("release_review_packet_integrity_projectile_ability_semantic_fixture") != null)
    and ($review.source_of_truth | contains("top-level inventory summary"))
  )
' "real checklist packet includes trnm-rts-evidence release-review packet assembly review binding inventory counts, manifest completeness, key RTS runtime artifacts, full-game visual/UI handoff, semantic fixtures, status handoff, and external blocker boundary; legacy semantic fixture packets without ready_items keep their focused failure counts"
require_artifact_json_expr cex_adapter_readiness_semantics cex_adapter_readiness '.contract_version == "trillionnium_world_cex_adapter_readiness_gate_v1" and .status == "cex_adapter_readiness_green" and .green == true and .source_of_truth == "trillionnium_world_cex_adapter_readiness_gate" and (.cex_import_rule | contains("trillionnium_world_crates_do_not_import_cex_service_internals")) and (.cex_import_rule | contains("cex_runtime_exports_json_evidence_for_trillionnium_release_review")) and (.raw_evidence_path | endswith("cex-production-adapter-readiness.raw.json")) and .input.fetch_status == "cached_raw_evidence" and (.input.fetch_detail | endswith("cex-production-adapter-readiness.raw.json")) and .observed.contract_version == "cex_trillionnium_world_production_adapter_v1" and .observed.protocol_contract == "trillionnium_world_runtime_adapter_v1" and .observed.domain_contract == "trillionnium_world_domain_v1" and .observed.status == "cex_production_adapter_bridge_ready" and .observed.cutover_status == "cex_production_impls_connected_to_standalone_traits" and .observed.cex_dependency_status == "consumer_entry_api_depends_on_trnm_world_api_without_trnm_world_importing_cex" and .observed.status_count == 6 and .observed.route_record_total >= 7000 and .observed.world_node_count >= 20 and .observed.repository_source == "cex_league_repository_normalized_world_tables" and .observed.ledger_reserve_source == "cex_world_contract_and_tactics_ledger_settlement" and .observed.metric_source == "cex_consumer_entry_metrics_projection" and .checks.contract_ok == true and .checks.protocol_ok == true and .checks.domain_ok == true and .checks.status_ok == true and .checks.cutover_ok == true and .checks.dependency_ok == true and .checks.adapters_ok == true and .checks.roles_ok == true and .checks.repository_ok == true and .checks.ledger_ok == true and .checks.evidence_ok == true and .checks.metric_ok == true and .checks.counts_ok == true' "CEX adapter readiness packet artifact binds inc